	'src/storage/hooks/useStorageValue.ts': `import { useCallback, useEffect, useState } from 'react'
import { getValue, setValue } from '@/storage/storageService'
import type { StoreName } from '@/storage/types'

export function useStorageValue<T>(
	storeName: StoreName,
	key: string,
	defaultValue: T,
): {
	value: T
	setValue: (next: T | ((current: T) => T)) => Promise<void>
	isLoading: boolean
	error: Error | null
} {
	const [value, setLocalValue] = useState<T>(defaultValue)
	const [isLoading, setIsLoading] = useState(true)
	const [error, setError] = useState<Error | null>(null)

	useEffect(() => {
		let cancelled = false

		async function load(): Promise<void> {
			try {
				const stored = await getValue<T>(storeName, key)
				if (!cancelled) {
					setLocalValue(stored ?? defaultValue)
					setError(null)
				}
			} catch (loadError) {
				if (!cancelled) {
					setError(
						loadError instanceof Error
							? loadError
							: new Error('Failed to load storage value'),
					)
				}
			} finally {
				if (!cancelled) {
					setIsLoading(false)
				}
			}
		}

		void load()

		return () => {
			cancelled = true
		}
	}, [storeName, key, defaultValue])

	const persist = useCallback(
		async (next: T | ((current: T) => T)): Promise<void> => {
			try {
				const resolved =
					typeof next === 'function'
						? (next as (current: T) => T)(value)
						: next
				setLocalValue(resolved)
				await setValue(storeName, key, resolved)
				setError(null)
			} catch (persistError) {
				setError(
					persistError instanceof Error
						? persistError
						: new Error('Failed to save storage value'),
				)
				throw persistError
			}
		},
		[storeName, key, value],
	)

	return {
		value,
		setValue: persist,
		isLoading,
		error,
	}
}
`,
	'src/storage/storageService.ts': `import { getDb } from './db'
import type { StoreName } from './types'

export async function getValue<T>(
	storeName: StoreName,
	key: string,
): Promise<T | undefined> {
	const db = await getDb()
	return db.get(storeName, key) as Promise<T | undefined>
}

export async function setValue<T>(
	storeName: StoreName,
	key: string,
	value: T,
): Promise<void> {
	const db = await getDb()
	await db.put(storeName, value, key)
}

export async function deleteValue(
	storeName: StoreName,
	key: string,
): Promise<void> {
	const db = await getDb()
	await db.delete(storeName, key)
}

export async function getAllValues<T>(
	storeName: StoreName,
): Promise<T[]> {
	const db = await getDb()
	const keys = await db.getAllKeys(storeName)
	const values = await Promise.all(
		keys.map((key) => db.get(storeName, key) as Promise<T>),
	)
	return values
}
`,
